fun main() {
    // 1) Coincidencia simple de valores
    val x = 2
    when (x) {
        1 -> println("Bir")
        2, 3 -> println("Kiçik rəqəm: $x")   // varios valores, separados por comas
        else -> println("Digər")
    }

    // 2) Como expresión + un rango
    val gun = 3
    val tip = when (gun) {
        in 1..5 -> "İş günü"
        6, 7 -> "İstirahət"
        else -> "Yanlış gün"
    }
    println(tip)

    // 3) Comprobación de tipo (is): entra en juego el smart cast
    val obyekt: Any = 42
    when (obyekt) {
        is Int -> println("Rəqəm")
        is String -> println("Uzunluq: ${obyekt.length}")  // automáticamente es un String
        is List<*> -> println("Siyahı, ${obyekt.size} element")
        else -> println("Naməlum tip")
    }

    // 4) when sin argumento: sustituye a una cadena if-else
    val temperatur = 5
    val geyim = when {
        temperatur < 0 -> "Qalın palto"
        temperatur in 1..10 -> "1-dən 10-a qədər"
        temperatur in 11..20 -> "Yüngül gödəkçə"
        else -> "Köynək"
    }
    println(geyim)

    // 5) Devolver directamente el resultado de when
    println(olcuAdi(150))
}

