fun main() {
    // break: detiene el bucle por completo
    for (i in 1..5) {
        if (i == 3) break
        print("$i ")
    }
    println()

    // continue: salta el paso actual
    for (i in 1..5) {
        if (i % 2 == 0) continue
        print("$i ")
    }
    println()

    // Una etiqueta: para salir de bucles anidados
    xarici@ for (i in 1..3) {
        for (j in 1..3) {
            if (i * j == 2) {
                println("Tapıldı: ($i, $j)")
                break@xarici     // sale de ambos bucles
            }
        }
    }
}

