fun main() {
    val boyuk = (1..1_000_000).toList()

    // LISTA NORMAL: ¡una lista nueva de un millón de elementos en cada paso!
    val a = boyuk
        .map { it * 2 }        // 1 000 000 elementos
        .filter { it > 10 }    // 999 995 elementos
        .take(2)               // solo necesitábamos 2...

    // SEQUENCE: fluye elemento a elemento, hace solo el trabajo necesario
    val b = boyuk.asSequence()
