abstract class Fiqur(val ad: String) {
    // Un método sin cuerpo: las subclases deben implementarlo
    abstract fun sahe(): Double

    // Un método con cuerpo: sobrescribirlo es opcional
    open fun cap() = println("$ad sahəsi: ${"%.2f".format(sahe())}")
}

class Daire(val radius: Double) : Fiqur("Dairənin") {
    override fun sahe() = Math.PI * radius * radius
}

class Duzbucaqli(val en: Double, val boy: Double) : Fiqur("Düzbucaqlının") {
    override fun sahe() = en * boy
}

fun main() {
    val fiqurlar = listOf(Daire(5.0), Duzbucaqli(4.0, 6.0))
    fiqurlar.forEach { it.cap() }
    println("Cəmi sahə: ${"%.2f".format(fiqurlar.sumOf { it.sahe() })}")
}

