// "by": reenvía todos los métodos de MutableList a la lista interna
class LoglayanSiyahi<T>(
    private val daxili: MutableList<T> = mutableListOf()
) : MutableList<T> by daxili {

    // Sobrescribimos solo el método que necesitamos
    override fun add(element: T): Boolean {
        println("Loglanır: $element əlavə olundu")
        return daxili.add(element)
    }

    // toString es miembro de Any, no de la interfaz: "by" no lo reenvía
    override fun toString() = daxili.toString()
}

fun main() {
    val s = LoglayanSiyahi<String>()
    s.add("Kotlin")
    println(s)          // [Kotlin]: nuestro propio toString
    println(s.size)     // mientras que size se reenvió a la lista interna
}

