sealed class Netice<out T> {
    data object Yuklenir : Netice<Nothing>()
    data class Ugurlu<T>(val data: T) : Netice<T>()
    data class Xeta(val mesaj: String, val kod: Int) : Netice<Nothing>()
}

fun emalEt(n: Netice<List<String>>): String = when (n) {
    // NO HACE FALTA else: el compilador conoce todos los casos
    is Netice.Yuklenir -> "Yüklənir..."
    is Netice.Ugurlu -> "Uğurlu: ${n.data.size} element"   // smart cast
    is Netice.Xeta -> "Xəta: ${n.mesaj} (kod ${n.kod})"
}

fun main() {
    println(emalEt(Netice.Yuklenir))
    println(emalEt(Netice.Ugurlu(listOf("a", "b", "c"))))
    println(emalEt(Netice.Xeta("Şəbəkə əlçatmazdır", 503)))
}

