fun main() = runBlocking {
    val is1 = launch {
        try {
            repeat(100) { i ->
                println("İşlənir $i")
                delay(100)          // un punto que tiene en cuenta la cancelación
            }
        } catch (e: CancellationException) {
            println("Ləğv olundu")
            throw e                 // DEBE volver a lanzarse
        } finally {
            // withContext(NonCancellable) { ... }: si la limpieza es suspend
